	/*
     * @param	event CreateProcedureEvent
     */
    @EventHandler( payloadType=CreateProcedureEvent.class )
    public void handle( CreateProcedureEvent event) {
	    LOGGER.info("handling CreateProcedureEvent - " + event );
	    Procedure entity = new Procedure();
            entity.setProcedureId( event.getProcedureId() );
            entity.setProcedureCode( event.getProcedureCode() );
            entity.setStartDateTime( event.getStartDateTime() );
            entity.setEndDateTime( event.getEndDateTime() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllProcedure( entity );
    }

    /*
     * @param	event UpdateProcedureEvent
     */
    @EventHandler( payloadType=UpdateProcedureEvent.class )
    public void handle( UpdateProcedureEvent event) {
    	LOGGER.info("handling UpdateProcedureEvent - " + event );
    	
	    Procedure entity = new Procedure();
            entity.setProcedureId( event.getProcedureId() );
            entity.setProcedureCode( event.getProcedureCode() );
            entity.setStartDateTime( event.getStartDateTime() );
            entity.setEndDateTime( event.getEndDateTime() );
            entity.setEncounter( event.getEncounter() );
            entity.setPerformer( event.getPerformer() );
            entity.setProcedureOrder( event.getProcedureOrder() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindProcedure( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllProcedure( entity );        
    }
    
