    /**
     * Method to retrieve the Procedure via an ProcedurePrimaryKey.
     * @param 	id Long
     * @return 	Procedure
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Procedure handle( FindProcedureQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getProcedureId() );
    }
    
    /**
     * Method to retrieve a collection of all Procedures
     *
     * @param	query	FindAllProcedureQuery 
     * @return 	List<Procedure> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Procedure> handle( FindAllProcedureQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindProcedure,
 * but only if the id matches
 *
 * @param		entity	Procedure
 */
	protected void emitFindProcedure( Procedure entity ) {
		LOGGER.info("handling emitFindProcedure" );
		
	    queryUpdateEmitter.emit(FindProcedureQuery.class,
	                            query -> query.getFilter().getProcedureId().equals(entity.getProcedureId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllProcedure
	 * 
	 * @param		entity	Procedure
	 */
	protected void emitFindAllProcedure( Procedure entity ) {
		LOGGER.info("handling emitFindAllProcedure" );
		
	    queryUpdateEmitter.emit(FindAllProcedureQuery.class,
	                            query -> true,
	                            entity);
	}

